import React, { useState, useRef } from "react";
import { 
  X, User, Truck, AlertCircle, BookOpen, 
  Award, AlertTriangle, CheckCircle, Activity, MapPin 
} from "lucide-react";
import ScheduleTab from "../tabs/ScheduleTab";
import ReportsTab from "../tabs/ReportsTab";
import TrainingTab from "../tabs/TrainingTab";

// --- REUSABLE REPORT MODAL ---
const ReportDetailModal = ({ report, onClose }) => (
  <div className="fixed inset-0 z-[200] flex items-center justify-center p-6 bg-[#47510B]/90 backdrop-blur-md">
    <div className="bg-[#FDFAD8] w-full max-w-sm rounded-[50px] border-[10px] border-white overflow-hidden shadow-2xl animate-slide-up flex flex-col">
      <div className="h-44 w-full relative">
        <img src={report.img} alt="Evidence" className="w-full h-full object-cover" />
        <button onClick={onClose} className="absolute top-4 right-4 w-10 h-10 bg-white rounded-full flex items-center justify-center text-[#AB1717] shadow-xl border-2 border-[#AB1717]/10">
          <X size={20} strokeWidth={3} />
        </button>
      </div>
      <div className="p-8">
        <h4 className="text-2xl font-black text-[#47510B] uppercase italic leading-none">{report.title}</h4>
        <div className="flex items-center gap-2 mt-2 mb-4 opacity-40 italic">
          <MapPin size={12} />
          <span className="text-[10px] font-black uppercase tracking-tighter">{report.loc}</span>
        </div>
        <p className="p-5 bg-white rounded-3xl border-2 border-[#47510B]/10 italic text-sm text-[#47510B]/80 mb-6 shadow-inner">
          "{report.description}"
        </p>
        <button onClick={onClose} className="w-full py-5 bg-[#47510B] text-[#CAD23C] rounded-[25px] font-black uppercase text-sm shadow-xl active:scale-95 transition-all">
          Mark as Resolved
        </button>
      </div>
    </div>
  </div>
);

const WorkerDashboard = () => {
  const [activeTab, setActiveTab] = useState("schedule");
  const [isProfileOpen, setIsProfileOpen] = useState(false);
  const [selectedReport, setSelectedReport] = useState(null);
  const scrollRef = useRef(null);

  const reportData = {
    'LOC_04': { title: 'Waste Overflow', loc: 'Sector 4', description: 'Bin at the corner of 5th Ave is completely overflowing.', img: 'https://images.unsplash.com/photo-1605600611284-19561ad7ddf0?q=80&w=600' },
    'LOC_15': { title: 'Illegal Dumping', loc: 'East Gate', description: 'Construction debris left near the entrance.', img: 'https://images.unsplash.com/photo-1530587191325-3db32d826c18?q=80&w=600' }
  };

  const tabs = [
    { id: "schedule", label: "Tasks", icon: <Truck size={24} /> },
    { id: "reports", label: "Issues", icon: <AlertCircle size={24} /> },
    { id: "training", label: "Learn", icon: <BookOpen size={24} /> },
  ];

  const handleOpenReport = (locationId) => {
    setSelectedReport(reportData[locationId]);
  };

  const scrollToTab = (tabId) => {
    const index = tabs.findIndex(t => t.id === tabId);
    setActiveTab(tabId);
    scrollRef.current.scrollTo({ left: index * window.innerWidth, behavior: "smooth" });
  };

  const handleScroll = () => {
    if (scrollRef.current) {
      const index = Math.round(scrollRef.current.scrollLeft / window.innerWidth);
      if (tabs[index] && tabs[index].id !== activeTab) {
        setActiveTab(tabs[index].id);
      }
    }
  };

  return (
    <div className="h-screen w-screen bg-[#FDFAD8] font-sans relative overflow-hidden flex flex-col">

      {/* 1. REPORT MODAL (TOP LAYER) */}
      {selectedReport && <ReportDetailModal report={selectedReport} onClose={() => setSelectedReport(null)} />}

      {/* 2. PROFILE LAYER (MIDDLE LAYER) */}
      <div className={`fixed inset-0 z-[150] transition-all duration-700 ease-in-out ${isProfileOpen ? "translate-y-0 opacity-100" : "translate-y-full opacity-0 pointer-events-none"}`}>
         {/* ... Your Profile Code here ... */}
         <div className="w-full h-full bg-[#FDFAD8] p-8 overflow-y-auto">
            <button onClick={() => setIsProfileOpen(false)} className="mb-8 p-4 bg-white rounded-full shadow-lg"><X size={24}/></button>
            <h3 className="text-4xl font-black text-[#47510B] italic uppercase">Marcus Sterling</h3>
            {/* [Insert existing profile content here] */}
         </div>
      </div>

      {/* 3. MAIN DASHBOARD (BASE LAYER) */}
      <div className={`flex-1 flex flex-col transition-transform duration-700 ${isProfileOpen ? "scale-95 blur-sm" : "scale-100 blur-0"}`}>

        {/* HEADER */}
        <header className="pt-12 px-8 flex justify-between items-center bg-transparent z-40">
          <h2 className="text-3xl font-black italic text-[#47510B] uppercase tracking-tighter">
            {activeTab === 'schedule' ? "Today's Schedule" : activeTab}
            <span className="text-[#CAD23C]">.</span>
          </h2>
          <button onClick={() => setIsProfileOpen(true)} className="bg-[#47510B] p-1.5 pr-5 rounded-2xl flex items-center gap-3 border-2 border-white shadow-lg text-[#CAD23C]">
            <div className="w-9 h-9 rounded-xl bg-[#CAD23C] flex items-center justify-center text-[#47510B]"><User size={20} strokeWidth={3} /></div>
            <span className="font-black text-[11px] uppercase tracking-[0.2em]">Marcus.7729</span>
          </button>
        </header>

        {/* SWIPEABLE CONTENT */}
        <main ref={scrollRef} onScroll={handleScroll} className="flex-1 flex overflow-x-auto snap-x snap-mandatory no-scrollbar h-full">
          <section className="min-w-full h-full snap-start overflow-y-auto">
            <ScheduleTab onViewReport={handleOpenReport} />
          </section>
          <section className="min-w-full h-full snap-start overflow-y-auto">
            <ReportsTab onSelectReport={setSelectedReport} />
          </section>
          <section className="min-w-full h-full snap-start overflow-y-auto">
            <TrainingTab />
          </section>
        </main>

        {/* FOOTER NAV */}
        <footer className="h-32 flex items-center justify-center bg-transparent z-40 pointer-events-none">
          <nav className="bg-[#47510B]/95 backdrop-blur-xl border border-white/20 p-2 rounded-[40px] shadow-2xl flex items-center gap-2 pointer-events-auto">
            {tabs.map((tab) => (
              <button 
                key={tab.id} 
                onClick={() => scrollToTab(tab.id)} 
                className={`flex items-center gap-3 px-8 py-4 rounded-[30px] transition-all duration-300 ${activeTab === tab.id ? "bg-[#CAD23C] text-[#47510B] scale-105" : "text-white/40"}`}
              >
                {tab.icon}
                {activeTab === tab.id && <span className="text-[11px] font-[1000] uppercase tracking-widest">{tab.label}</span>}
              </button>
            ))}
          </nav>
        </footer>
      </div>
    </div>
  );
};

export default WorkerDashboard;
